    "次に挙げる行政に関連する法令の規定の空欄［ ア ］～［ エ ］に当てはまる語句の組合せとして、正しいものはどれか。\n行政不服審査法　第21条　第1項　審査請求をすべき行政庁が処分庁等と異なる場合における審査請求は、処分庁等を経由してすることができる。（以下略） 第3項　第1項の場合における審査請求期間の計算については、処分庁に審査請求書を提出し、又は処分庁に対し当該事項を陳述した時に、処分についての審査請求があったものと［ ア ］。\n行政事件訴訟法　第7条　行政事件訴訟に関し、この法律に定めがない事項については、［ イ ］。\n行政事件訴訟法　第36条　無効等確認の訴えは、当該処分又は裁決に続く処分により損害を受けるおそれのある者［ ウ ］当該処分又は裁決の無効等の確認を求めるにつき法律上の利益を有する者で、当該処分［ エ ］裁決の存否又はその効力の有無を前提とする現在の法律関係に関する訴えによって目的を達することができないものに限り、提起することができる。"
