    "離婚による財産分与について、[[dict:黙示的表示::1. 財産分与での具体的な現れ方\n財産分与の協議において、黙示的表示が認められる（または主張される）のは以下のようなケースです。\n\n特有財産の「共有化」への同意\n本来、結婚前から持っていた預金や相続した不動産は「特有財産」として分与の対象外です。しかし、その資金を夫婦の共同生活費の口座に入れ、長年区別せずに管理・使用していた場合、「これは二人の共有財産にする」という黙示の合意があったと判断され、分与対象に含まれることがあります。\n\n分与割合（1/2ルール）の修正\n原則として財産分与は2分の1ずつですが、一方が特殊な能力で多額の資産を築き、もう一方がそれを前提とした生活を送っていた（文句を言わず従っていた）場合など、**「この割合で分けることに黙示的に納得していた」**と主張されることがあります（ただし、裁判所が認めるハードルは高いです）。\n\n清算の終了（解決済み）の主張\n別居時に家財道具や一定の現金を分け合い、その後長期間、相手に何も請求せずに生活していた場合、相手方から**「あの時の分割で、財産分与の清算は終わったという黙示の合意があった」**と反論される材料になります。]]があれば、錯誤による取消しを主張できる",
