    "",
    "",
    "過去問での出題例と狙われるポイント\n過去の試験（行政書士試験など）では、以下のような形で問われています。\n\n1. 設置根拠と手続きのひっかけ\n出題パターン: 「特別区は、関係市町村の条例を定めることで設置できる」→ × 誤り\n\n解説: 「大都市地域特別区設置法」という特別な法律に基づき、住民投票で過半数の賛成を得る必要があります。条例だけで勝手に作ることはできません（平成28年 行政書士試験 問22など）。\n\n2. 「都」以外での設置可能性\n出題パターン: 「特別区は、都（東京都）にのみ置かれるものである」→ △（地方自治法上は○だが、特別法を含めると×）\n\n解説: 地方自治法（281条）の文面だけを見ると「特別区は、都に置く」とありますが、大都市地域特別区設置法によって、政令指定都市を持つ道府県（大阪府など）でも設置が可能になっています。この「法律の使い分け」が知識の差として試されます。\n\n3. 住民投票の性質\n出題パターン: 「大阪都構想のような特別区設置の住民投票は、法的拘束力のないアンケートに過ぎない」→ × 誤り\n\n解説: この住民投票は法律（設置法）に基づき、過半数の賛成がなければ設置の手続きを進めることができないため、非常に強い実質的な効力を持っています（令和7年 行政書士試験 問47の選択肢に関連）。\n\n整理：特別区設置の2つのルート\n混乱しないように、以下の2つの視点を分けて覚えておくのが試験対策のコツです。\n\n地方自治法（原則ルート）\n\n対象：東京都の23区。\n\n性質：法律によって最初から「都」に置かれるものとして規定されている。\n\n大都市地域特別区設置法（特例ルート）\n\n対象：政令指定都市を含む地域（大阪市など）。\n\n手続き：関係市町村の廃止 ＋ 住民投票（過半数の賛成）。\n\n学習のアドバイス\nこの部分は「最新の時事（大阪都構想の住民投票など）」と「法律の条文」がリンクする場所なので、試験では**「住民投票が必要かどうか」と「根拠となる法律名（自治法なのか特別法なのか）」**をセットで問うのが定番です。",
