    "1. 「原因」を作った人が負担する民法の考え方では、自分の土地に降った雨を適切に処理するのは、その土地の所有者の責任です。「自分の屋根のせいで、お隣に直接水が落ちる状態」を作っているのは自分ですから、それを防ぐための**雨どいの設置費用や工事費は、すべて設置する側（加害側）**が支払わなければなりません。2. 損害賠償も「加害側」の負担もし雨水のせいで隣の家の壁が腐食したり、庭が削れたりした場合は、その修理費用（損害賠償）も原因を作った側が負担します。3. 【重要】「自然な水」との違いに注意！試験でひっかけられやすいポイントですが、以下のケースとは区別してください。工作物（屋根など）からの雨水：今回のケース。屋根を作った人の負担で防がなければならない。自然に流れてくる水（高地から低地へ）：これは自然現象なので、下の土地の人は文句を言えません。もし下の土地の人が「水が流れてこないように堤防を作りたい」と思ったら、それは自分の費用で作ることになります。行政書士試験向けのまとめ表状況対策の費用負担根拠の考え方屋根からの雨水（工作物）屋根の所有者他人の権利を侵害しているため自然に流れる水対策したい側自然の理（ことわり）であるため「誰が原因を作っているか」で見分けると覚えやすいですよ。",
    "Gemini の回答\r\nご提示いただいた文章は、行政書士試験の民法（共有）において非常によく狙われる**「保存行為」と「損害賠償」**のルールに関するものです。\r\n\r\nこのケースを整理すると、以下のようになります。\r\n\r\n1. 建物収去・土地明け渡し請求（保存行為）\r\n共有者のひとりであるGは、単独でBに対して「建物を壊して出て行ってくれ（収去・明け渡し）」と言うことができます。\r\n\r\n理由: 自分の持分を守るための**「保存行為」**にあたるからです。\r\n\r\nポイント: 全員の同意を得る必要はありません。不法占拠者に対しては、各共有者が自分の権利として「全部返せ」と主張できます。\r\n\r\n2. 損害賠償請求（または不当利得返還請求）\r\nここが試験で最も「ひっかけ」として出やすいポイントです。GはBに対し、損害賠償（または賃料相当額の返還）を請求できますが、**「自分の持分（シェア）の範囲内」**に限られます。\r\n\r\n理由: お金（金銭債権）は、持分に応じて分けられるもの（可分）と考えられるためです。\r\n\r\n注意点: 「共有者全員のために、全額払え」と請求することはできません。\r\n\r\nまとめ表：Gがひとりでできること\r\n請求の内容\t請求できる範囲\t法律上の分類\r\n建物の収去（取り壊し）\t全部\t保存行為\r\n土地の明け渡し\t全部\t保存行為\r\n損害賠償・不当利得\t自分の持分のみ\t可分債権\r\n行政書士試験に向けた対策\r\n試験では、「保存行為だから、損害賠償も全額請求できる」という誤った選択肢がよく出されます。\r\n\r\n物体（土地・建物）の返還・取り壊し → ひとりで「全部」OK\r\n\r\nお金（損害賠償・賃料） → ひとりで「自分の分だけ」OK\r\n\r\nこの違いをしっかり区別しておけば、この手の問題は得点源になります。\n\n1. 「通知」は原則として義務ではないおっしゃる通り、共有者（R・S・T）が土地を分ける際、その土地の上の建物所有者（C）などに対して、「これから分割協議をしますよ」といちいち通知する義務は法律上ありません。2. 利害関係人は「自己の費用」で参加できる共有物の分割によって不利益を被るおそれがある人（抵当権者や、今回のケースのような借地権者など）は、分割の協議や訴訟に**自分の費用で参加（補助参加）**することができます。3. 【重要】「通知」が必要になるケース（修正点）ここが試験で狙われるポイントですが、**「もしCが、あらかじめ『分割するときは教えてね』と請求（参加の請求）をしていた場合」**は話が変わります。Cから請求があった場合： 共有者（R・S・T）はCに通知しなければなりません。通知を無視して分割した場合： その分割の結果をCに対抗（主張）することができなくなります。行政書士試験に向けた整理図状況通知の義務Cができること通常時なし自己の費用で分割に参加できるCが「参加したい」と事前に伝えていた時あり通知を待って参加できる引っかけ対策のポイント試験では以下のような出し方をされます。×「共有者は、常に利害関係人に通知しなければならない」（→請求がなければ不要）×「分割の費用は、参加する利害関係人が負担させることはできない」（→参加費用は自己負担が原則）「通知は原則不要だが、参加したいと言ってきた人を無視して進めると、後でその人に文句を言えなくなる」とセットで覚えておくと完璧です。\n\n1. 「競売分割」は裁判所の最終手段共有物の分割について話し合いがまとまらず、裁判になった場合、裁判所が**「現物分割も賠償分割も無理だ」**と判断したときに初めて、「競売して代金を分けなさい」という判決（競売分割）を出します。強制力: 裁判所が命じるものなので、共有者の誰かが反対していても、強制的に競売（オークション）にかけられます。2. 話し合いで売る場合は「換価分割」一方、裁判を通さず、R・S・Tの全員が「この土地を売って、お金を3等分しよう」と合意して売却することを、一般に**「換価分割（かんかぶんかつ）」**と呼びます。任意: 全員の合意が必要です。自分たちで不動産業者を探して普通に売る（任意売却）ことができます。3. 【重要】試験で狙われる「判決」のポイント行政書士試験の民法では、**「裁判所がどのような判決を出せるか」**が問われます。分割の種類誰が決める？性質現物分割裁判所 or 協議土地を物理的に分ける（原則）賠償分割裁判所 or 協議誰かが取得し、残りにお金を払う競売分割裁判所のみ強制的に競売にかける（最終手段）換価分割協議のみ全員合意の上で普通に売却する注意すべきひっかけ問題「裁判所は、共有者の1人が反対していても、競売分割を命じることができるか？」→ YES。 判決には強制力があるため、反対者がいても競売に進みます。「現物分割が可能な場合でも、裁判所はいきなり競売分割を命じることができるか？」→ NO。 原則は現物分割（または賠償分割）であり、それが「不可能」または「価値を著しく損なう」場合でなければ競売は選べません。まとめ「競売」という言葉がつくものは、裁判所が強制的に行う手続きだと考えて間違いありません。話し合いで平和に売るなら、それは単なる「売却（換価分割）」です。",
