    "\"判例名・判決日】\nNHK受信料訴訟（最大判平成29年12月6日）\n\n空欄の正解\nこの判決文は、行政書士試験の過去問（平成30年度・問題27）として実際に出題されています。\n\n［ ア ］： 自律\n\n［ イ ］： 二元体制\n\n［ ウ ］： 多元的\n\n［ エ ］： 営利\n\n1. 判例のストーリー\n事案： テレビを設置しているがNHKと受信契約を結ばない男性に対し、NHKが契約締結と受信料の支払いを求めて提訴しました。男性側は「契約を強制するのは、憲法が保障する契約の自由や表現の自由に反する」と主張しました。\n\n結論： 合憲（受信契約を強制する制度は有効）。\n\n理由： NHKは、特定のスポンサーや国家権力に左右されない「財政的基盤」を持つことで、国民に公平・不偏な情報を提供する役割（国民の知る権利の充足）を担っているため、その財源を広く国民から集める制度は合理的であるとされました。\n\n2. 解説：各キーワードの論点\n［ ア ］ 自律（自律的）\n放送法1条にある「放送の不偏不党、真実及び自律を保障すること」という文言からの引用です。外部（政府や企業）からの圧力に屈せず、自分たちでルールを決め、独立して運営することを指します。\n\n［ イ ］ 二元体制\nこれが日本の放送制度の最大の特徴です。\n\n公共放送（NHK）： 受信料で運営される。\n\n民間放送（民放）： 広告料（スポンサー）で運営される。\nこの2つが並び立ち、互いに刺激し合って放送の質を高める仕組みを「二元体制」と呼びます。\n\n［ ウ ］ 多元的\n「特定の意見」だけでなく、社会にある「多様な意見」を反映させる基盤のことです。民主主義を支えるためには、放送が多元的（バラエティに富んでいること）である必要があります。\n\n［ エ ］ 営利\nNHKは公共の福祉のために活動する団体であり、利益を追求する 営利 目的の業務は禁止されています。だからこそ、広告（CM）を流さず、受信料のみで運営されているのです。\n\n3. 試験で狙われる択一式のポイント\nこの判例では、多肢選択式以外にも以下の点が択一式（5肢択一）でよく問われます。\n\n契約成立のタイミング：\nNHKが「契約してください」と申し込んだだけでは契約は成立しません。相手が拒否した場合は、NHKが裁判を起こし、**「裁判の判決が確定した時」**に初めて契約が成立します（通知が届いた時点ではありません）。\n\n時効の起算点：\n受信料の消滅時効は5年ですが、これは「契約が成立した時」から数えて、過去に遡って支払う必要があります。\n\n憲法21条（知る権利）：\nこの判決は、受信料制度が「国民の知る権利」を実質的に保障するためのものである、という理屈で合憲判断を導き出しています。\n\n4. 学習のヒント\nこの判例は、「憲法（知る権利・表現の自由）」と「行政法（放送法という個別法）」、さらには**「民法（契約の成立・時効）」**の3つの知識がクロスオーバーする非常に珍しい判例です。\n\n公共の福祉 ＝ 受信料制度の正当化\n\n二元体制 ＝ NHKと民放の共存\n\nという図式で覚えておくと、他の問題にも応用が効きます。\"",
